		// The native commit has consumed any cursor opened after preparation; never close its freed handle.
		retireWriterCursors(false);
		Root previous = current;
		current = prepared;
		prepared = null;
		nativeTxnId = committedNativeTxnId;
		baseEpoch = preparedEpoch;
		dirty = preparedDirty;
		drop(previous);
		clearWriter();
